import fs from '@ohos.file.fs'
import util from '@ohos.util'

export interface Page4PlaceBindingPayload {
  homeNodeId: string
  companyNodeId: string
}

export class Page4PlaceBindingStorageModule {
  static ensurePlaceBindingsLoaded(
    path: string,
    isValidGridId: (id: string) => boolean
  ): { homeNodeId: string, companyNodeId: string } {
    let f: fs.File | undefined = undefined
    try {
      f = fs.openSync(path, fs.OpenMode.READ_ONLY)
      const st: fs.Stat = fs.statSync(path)
      const size: number = Number(st.size)
      if (!Number.isFinite(size) || size <= 0 || size > 4096) return { homeNodeId: '', companyNodeId: '' }
      const buf: ArrayBuffer = new ArrayBuffer(Math.trunc(size))
      const readLen: number = fs.readSync(f.fd, buf)
      if (readLen <= 0) return { homeNodeId: '', companyNodeId: '' }
      const bytes: Uint8Array = new Uint8Array(buf, 0, readLen)
      const txt: string = new util.TextDecoder('utf-8', { ignoreBOM: true }).decodeWithStream(bytes, { stream: false })
      const parsed: Page4PlaceBindingPayload = JSON.parse(txt) as Page4PlaceBindingPayload
      const home: string = String(parsed.homeNodeId ?? '').trim().toUpperCase()
      const company: string = String(parsed.companyNodeId ?? '').trim().toUpperCase()
      return {
        homeNodeId: isValidGridId(home) ? home : '',
        companyNodeId: isValidGridId(company) ? company : ''
      }
    } catch (_) {
      return { homeNodeId: '', companyNodeId: '' }
    } finally {
      if (f) {
        try { fs.closeSync(f.fd) } catch (_) {}
      }
    }
  }

  static persistPlaceBindings(path: string, payload: Page4PlaceBindingPayload): boolean {
    let f: fs.File | undefined = undefined
    try {
      const txt: string = JSON.stringify(payload)
      try { fs.unlinkSync(path) } catch (_) {}
      f = fs.openSync(path, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE)
      fs.writeSync(f.fd, txt)
      return true
    } catch (_) {
      return false
    } finally {
      if (f) {
        try { fs.closeSync(f.fd) } catch (_) {}
      }
    }
  }
}

import fs from '@ohos.file.fs'
import { Page4ReplyText } from '../config/Page4ReplyText'

export type Page4PlaceRole = 'home' | 'company'

export interface Page4PlaceBindingPayload {
  homeNodeId?: string
  companyNodeId?: string
}

export interface Page4PlaceBindingPlan {
  role: Page4PlaceRole
  placeText: string
}

export interface Page4AliasItem {
  name: string
  destNodeId: string
  tsMs: number
}

export class Page4PoiBindingModule {
  static mapPoiNameToNode(
    input: string,
    mappings: Array<{ node: string, aliases: Array<string> }>,
    normalizePlaceInput: (text: string) => string
  ): string {
    const raw: string = input.trim()
    if (raw.length <= 0) return ''
    const normalized: string = normalizePlaceInput(raw)
    for (let i: number = 0; i < mappings.length; i++) {
      const one = mappings[i]
      for (let j: number = 0; j < one.aliases.length; j++) {
        const alias: string = one.aliases[j]
        if (raw.indexOf(alias) >= 0 || normalized.indexOf(normalizePlaceInput(alias)) >= 0) {
          return one.node.trim().toUpperCase()
        }
      }
    }
    return ''
  }

  static buildPoiMappingSummaryText(
    mappings: Array<{ node: string, aliases: Array<string> }>,
    aliasDict: Array<Page4AliasItem>,
    isValidNode: (id: string) => boolean,
    formatPlaceBinding: (role: Page4PlaceRole) => string
  ): string {
    const merged: Record<string, Array<string>> = {}
    for (let i: number = 0; i < mappings.length; i++) {
      const one = mappings[i]
      const node: string = one.node.trim().toUpperCase()
      if (!isValidNode(node)) continue
      if (!merged[node]) merged[node] = []
      for (let j: number = 0; j < one.aliases.length; j++) {
        const alias: string = one.aliases[j].trim()
        if (alias.length <= 0) continue
        if (merged[node].indexOf(alias) < 0) merged[node].push(alias)
      }
    }
    const nodes: Array<string> = Object.keys(merged).sort()
    const lines: Array<string> = []
    for (let i: number = 0; i < nodes.length; i++) lines.push(`${nodes[i]}: ${merged[nodes[i]].join(' / ')}`)

    const dynamicAliases: Array<string> = []
    for (let i: number = 0; i < aliasDict.length; i++) {
      const one: Page4AliasItem = aliasDict[i]
      if (!isValidNode(one.destNodeId)) continue
      if (one.name === '物流中心' || one.name === '快递点') continue
      dynamicAliases.push(`${one.name}->${one.destNodeId}`)
    }
    return Page4ReplyText.poiMappingSummary(lines, formatPlaceBinding('home'), formatPlaceBinding('company'), dynamicAliases)
  }

  static exportPoiMappingsToFile(
    exportPath: string,
    homeNodeId: string,
    companyNodeId: string,
    mappings: Array<{ node: string, aliases: Array<string> }>,
    aliases: Array<Page4AliasItem>
  ): { ok: boolean, path: string, error: string } {
    let f: fs.File | undefined = undefined
    try {
      const payload: Record<string, Object | string | number | boolean | Array<Object | string | number | boolean>> = {
        generatedAtMs: Date.now(),
        homeNodeId,
        companyNodeId,
        mappings: mappings as unknown as Array<Object>,
        aliases: aliases as unknown as Array<Object>
      }
      const txt: string = JSON.stringify(payload, null, 2)
      try { fs.unlinkSync(exportPath) } catch (_) {}
      f = fs.openSync(exportPath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE)
      fs.writeSync(f.fd, txt)
      return { ok: true, path: exportPath, error: '' }
    } catch (e) {
      const msg: string = e instanceof Error ? e.message : 'write failed'
      return { ok: false, path: exportPath, error: msg }
    } finally {
      if (f) {
        try { fs.closeSync(f.fd) } catch (_) {}
      }
    }
  }

  static parsePlaceRoleToken(raw: string): '' | Page4PlaceRole {
    const x: string = raw.trim().toLowerCase()
    if (x.indexOf('home') >= 0 || x.indexOf('物流中心') >= 0) return 'home'
    if (x.indexOf('company') >= 0 || x.indexOf('快递点') >= 0 || x.indexOf('公司仓库') >= 0) return 'company'
    return ''
  }

  static placeRoleText(role: '' | Page4PlaceRole): string {
    return Page4ReplyText.placeRoleText(role)
  }

  static parsePlaceBindingRequest(text: string): { role: Page4PlaceRole, placeText: string } | undefined {
    const src: string = text.trim()
    const roleFirst: RegExpMatchArray | null =
      src.match(/(?:把|将)?\s*(物流中心|快递点|公司仓库|home|company)\s*(?:设置为|设为|改为|改成|定义为|记为)\s*(.+)$/i)
    if (roleFirst && roleFirst.length >= 3) {
      const roleRaw: string = String(roleFirst[1] ?? '')
      const placeText: string = String(roleFirst[2] ?? '').trim()
      const role: '' | Page4PlaceRole = this.parsePlaceRoleToken(roleRaw)
      if (!role || placeText.length <= 0) return undefined
      return { role, placeText }
    }

    const placeFirst: RegExpMatchArray | null =
      src.match(/(?:把|将)?\s*(.+?)\s*(?:设置为|设为|改为|改成|定义为|记为)\s*(物流中心|快递点|公司仓库|home|company)\s*$/i)
    if (!placeFirst || placeFirst.length < 3) return undefined
    const placeText: string = String(placeFirst[1] ?? '').trim()
    const roleRaw: string = String(placeFirst[2] ?? '')
    const role: '' | Page4PlaceRole = this.parsePlaceRoleToken(roleRaw)
    if (!role || placeText.length <= 0) return undefined
    return { role, placeText }
  }

  static wantsPlaceBindingQuery(rawLower: string, containsAny: (text: string, keys: Array<string>) => boolean): { askHome: boolean, askCompany: boolean } | undefined {
    if (containsAny(rawLower, ['设置为', '设为', '改为', '改成', '定义为', '记为', '当成', '作为'])) {
      return undefined
    }
    const ask: boolean = containsAny(rawLower, ['物流中心', '快递点', '公司仓库']) &&
      containsAny(rawLower, ['在哪', '是什么', '查询', '查看', '配置', '设置了吗', '有没有设置', '是否设置'])
    if (!ask) return undefined
    const askHome: boolean = containsAny(rawLower, ['物流中心', 'home']) || !containsAny(rawLower, ['快递点', 'company', '公司仓库'])
    const askCompany: boolean = containsAny(rawLower, ['快递点', 'company', '公司仓库']) || !containsAny(rawLower, ['物流中心', 'home'])
    return { askHome, askCompany }
  }

  static formatPlaceBinding(role: Page4PlaceRole, node: string, isValidNode: (id: string) => boolean): string {
    const up: string = node.trim().toUpperCase()
    return Page4ReplyText.formatPlaceBinding(role, up, isValidNode(up))
  }
}

import { Page1Action } from '../../page1/types/Page1Types'
import { Page4PlannedTask } from '../modules/Page4OpenClawPlanQaModule'

export interface Page4TaskParseDeps {
  extractDestNode: (text: string) => string
  isValidGridId: (id: string) => boolean
  resolveActionByText: (lower: string) => Page1Action | undefined
  looksLikeCaptureFrameIntent: (lower: string) => boolean
  containsAny: (text: string, keys: Array<string>) => boolean
}

export class Page4OrchestrationLayer {
  static actionName(action: Page1Action): string {
    if (action === Page1Action.GO) return '前进'
    if (action === Page1Action.BACK) return '后退'
    if (action === Page1Action.LEFT) return '左转'
    if (action === Page1Action.RIGHT) return '右转'
    if (action === Page1Action.UTURN) return '掉头'
    if (action === Page1Action.STOP) return '停止'
    if (action === Page1Action.SCRAM) return '紧急停止'
    if (action === Page1Action.TFTA) return 'TFTA'
    return '动作'
  }

  static resolveActionByText(
    textLower: string,
    lastAction: Page1Action | undefined,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): Page1Action | undefined {
    if (containsAny(textLower, ['再来一次', '重复上一动作', '继续刚才动作', 'repeat'])) return lastAction
    if (containsAny(textLower, ['紧急停止', '急停', 'scram'])) return Page1Action.SCRAM
    if (containsAny(textLower, ['停止', '停车', 'stop'])) return Page1Action.STOP
    if (containsAny(textLower, ['前进', '向前', 'go'])) return Page1Action.GO
    if (containsAny(textLower, ['后退', '倒车', 'back'])) return Page1Action.BACK
    if (containsAny(textLower, ['左转'])) return Page1Action.LEFT
    if (containsAny(textLower, ['右转'])) return Page1Action.RIGHT
    if (containsAny(textLower, ['掉头'])) return Page1Action.UTURN
    return undefined
  }

  static looksLikeCaptureFrameIntent(
    textLower: string,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): boolean {
    return containsAny(textLower, [
      '获取当前摄像头画面',
      '获取当前画面',
      '抓取当前画面',
      '读取当前画面',
      '保存当前画面',
      '给我当前画面',
      '看一下当前画面',
      'camera frame',
      'current frame',
      'capture frame'
    ])
  }

  static splitPromptToClauses(text: string): Array<string> {
    const src: string = text
      .replace(/然后|接着|随后|并且|并且再|同时|接下来|再去|再到/g, '|')
      .replace(/[，,；;。.!！?？\n]/g, '|')
    const raw: Array<string> = src.split('|')
    const out: Array<string> = []
    for (let i: number = 0; i < raw.length; i++) {
      const one: string = raw[i].trim()
      if (one.length > 0) out.push(one)
    }
    return out
  }

  static parseTaskFromClause(clause: string, deps: Page4TaskParseDeps): Page4PlannedTask | undefined {
    const lower: string = clause.toLowerCase()
    const dest: string = deps.extractDestNode(clause)
    if (dest.length > 0 && deps.isValidGridId(dest)) return { kind: 'route', destNodeId: dest }

    const action: Page1Action | undefined = deps.resolveActionByText(lower)
    if (action !== undefined) return { kind: 'action', action: action }

    if (deps.containsAny(lower, ['开启自动跟随', '打开自动跟随', '自动跟随开启', '自动驾驶开启'])) return { kind: 'auto_follow', enabled: true }
    if (deps.containsAny(lower, ['关闭自动跟随', '停止自动跟随', '自动跟随关闭', '自动驾驶关闭'])) return { kind: 'auto_follow', enabled: false }
    if (deps.containsAny(lower, ['开启真车模式', '真车模式', 'real_send'])) return { kind: 'send_mode', mode: 'REAL_SEND' }
    if (deps.containsAny(lower, ['开启仿真模式', '仿真模式', 'dry_run', '关闭真车模式'])) return { kind: 'send_mode', mode: 'DRY_RUN' }
    if (deps.looksLikeCaptureFrameIntent(lower)) return { kind: 'capture_frame' }
    if (deps.containsAny(lower, ['查询状态', '状态', 'status'])) return { kind: 'query_status' }
    if (deps.containsAny(lower, ['识别状态', '视觉状态', '识别结果', 'vision'])) return { kind: 'query_vision' }
    if (deps.containsAny(lower, ['网络', '通信'])) return { kind: 'query_comm' }
    if (deps.containsAny(lower, ['视频', '相机'])) return { kind: 'query_video' }
    return undefined
  }

  static parseLocalPlannedTasks(text: string, deps: Page4TaskParseDeps): Array<Page4PlannedTask> {
    const clauses: Array<string> = this.splitPromptToClauses(text)
    const out: Array<Page4PlannedTask> = []
    for (let i: number = 0; i < clauses.length; i++) {
      const task: Page4PlannedTask | undefined = this.parseTaskFromClause(clauses[i], deps)
      if (!task) continue
      out.push(task)
    }
    return out
  }

  static looksLikeMultiTask(text: string, containsAny: (text: string, keys: Array<string>) => boolean): boolean {
    const x: string = text.trim()
    if (x.length <= 0) return false
    if (this.splitPromptToClauses(x).length >= 2) return true
    return containsAny(x, ['然后', '接着', '并且', '同时', '再', '随后', ';', '；', ',', '，'])
  }

  static looksLikeControlIntent(
    text: string,
    lower: string,
    extractDestNode: (text: string) => string,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): boolean {
    if (text.trim().length <= 0) return false
    if (this.looksLikeMultiTask(text, containsAny)) return true
    if (extractDestNode(text).length > 0) return true
    const keywords: Array<string> = [
      '导航', '前往', '去', '到',
      '返仓', '回仓', '返航', '回基地', '回中心', '回物流中心', '回快递点', '回仓库', '返仓库',
      '前进', '后退', '左转', '右转', '掉头', '停止', '急停', '刹车',
      '自动跟随', '自动驾驶', '真车模式', '仿真模式', 'real_send', 'dry_run',
      '撤销', '回到安全点',
      '抓拍', '截图', '拍照', '相机', '视频',
      '查询状态', '状态', '识别', '视觉', '通信', '网络',
      '读取文件', '读文件', '文件内容', '进程列表', '查询进程', '执行命令', '命令行', 'process', 'read_file', 'exec_cmd'
    ]
    return containsAny(lower, keywords)
  }
}

import { GridIdCodec } from '../../page1/app/PathPlannerAStar'
import { Page4AliasItem } from './Page4PoiBindingModule'

export class Page4LocalIntentModule {
  static containsAny(text: string, keys: Array<string>): boolean {
    const x: string = text.toLowerCase()
    for (let i: number = 0; i < keys.length; i++) {
      if (x.indexOf(keys[i].toLowerCase()) >= 0) return true
    }
    return false
  }

  static learnAliasFromText(text: string, aliasDict: Array<Page4AliasItem>): { message: string, aliasDict: Array<Page4AliasItem> } {
    const src: string = text.trim()
    if (src.length <= 0) return { message: '', aliasDict }
    const patterns: Array<RegExp> = [
      /(?:把|将)\s*([^，。；;,\s]{1,16})\s*(?:记为|设为|设置为|定义为)\s*([A-Ga-g]\d{1,2})/,
      /^([^，。；;,\s]{1,16})\s*(?:是|等于)\s*([A-Ga-g]\d{1,2})$/
    ]
    for (let i: number = 0; i < patterns.length; i++) {
      const m: RegExpMatchArray | null = src.match(patterns[i])
      if (!m || m.length < 3) continue
      const name: string = m[1].trim()
      const destNodeId: string = m[2].trim().toUpperCase()
      if (!GridIdCodec.isValidId(destNodeId)) return { message: `"${destNodeId}" 不是合法点位，别名学习失败。`, aliasDict }
      if (name.length <= 0) return { message: '别名为空，学习失败。', aliasDict }
      let replaced: boolean = false
      const next: Array<Page4AliasItem> = []
      for (let k: number = 0; k < aliasDict.length; k++) {
        const cur: Page4AliasItem = aliasDict[k]
        if (cur.name === name) {
          replaced = true
          next.push({ name, destNodeId, tsMs: Date.now() })
        } else next.push(cur)
      }
      if (!replaced) next.push({ name, destNodeId, tsMs: Date.now() })
      return { message: replaced ? `已更新别名：${name} -> ${destNodeId}` : `已学习别名：${name} -> ${destNodeId}`, aliasDict: next }
    }
    return { message: '', aliasDict }
  }

  static resolveAliasNode(text: string, aliasDict: Array<Page4AliasItem>, normalizePlaceInput: (text: string) => string): string {
    const src: string = text.trim()
    if (src.length <= 0) return ''
    for (let i: number = 0; i < aliasDict.length; i++) {
      const item: Page4AliasItem = aliasDict[i]
      if (item.name.length <= 0) continue
      if (src.indexOf(item.name) >= 0) return item.destNodeId
      if (normalizePlaceInput(src).indexOf(normalizePlaceInput(item.name)) >= 0) return item.destNodeId
    }
    return ''
  }

  static resolveContextDestNode(input: string, lastDestNodeId: string): string {
    const x: string = input.trim()
    if (x.length <= 0) return ''
    if (!GridIdCodec.isValidId(lastDestNodeId)) return ''
    if (this.containsAny(x, ['那里', '那儿', '刚才那个点', '上一目的地', '上一个目的地', '原目的地'])) return lastDestNodeId
    return ''
  }
}

﻿import { OpenClawChatMessage } from '../../../services/assistant/OpenClawGatewayClient'
import { Page4GatewayLayer, Page4GatewayState } from '../gateway/Page4GatewayLayer'
import { Page4PlannedTask } from './Page4OpenClawPlanQaModule'

export interface Page4OpenClawTaskPlannerDeps {
  resolveTokenCandidates: () => Array<string>
  resolveHosts: () => Array<string>
  gatewayState: () => Page4GatewayState
  applyGatewayState: (state: Page4GatewayState) => void
  mapOpenClawPlan: (text: string) => Array<Page4PlannedTask>
  buildRuntimePrompt: () => string
  connectTimeoutMs: () => number
  readTimeoutMs: () => number
  model: string
}

export class Page4OpenClawTaskPlannerModule {
  static async planTasksByOpenClaw(input: string, deps: Page4OpenClawTaskPlannerDeps): Promise<Array<Page4PlannedTask>> {
    const tokenCandidates: Array<string> = deps.resolveTokenCandidates()
    if (tokenCandidates.length <= 0) return []
    const hosts: Array<string> = deps.resolveHosts()
    if (hosts.length <= 0) return []

    const messages: Array<OpenClawChatMessage> = [
      {
        role: 'system',
        content:
          '你是无人物流车任务解析器。把用户一句话解析为任务数组，输出严格 JSON：' +
          '{"tasks":[{"type":"route","dest":"B2"},{"type":"method","name":"set_auto_follow","args":{"enabled":true}}]}。' +
          'type 允许 route/action/auto_follow/send_mode/capture_frame/undo/query_status/query_vision/query_comm/query_video/method。' +
          'route.dest 必须是 A1-G7 这样的点位；action 仅 GO/BACK/LEFT/RIGHT/UTURN/STOP/SCRAM；' +
          'auto_follow 使用 enabled=true/false；send_mode 使用 mode=REAL_SEND/DRY_RUN。' +
          'method.name 仅允许 start_manual_route/send_action/set_auto_follow/set_send_mode/speak_text/undo_to_safe_point/get_camera_frame/query_status/query_vision/query_comm/query_video/read_file/process_list/exec_cmd/set_recognition/set_auto_report/set_vision_mode/set_adaptive_strategy/tablet_set_alarm/tablet_open_app/tablet_list_alarm/tablet_start_ability/tablet_open_url。' +
          'method.args: start_manual_route 传 dest; send_action 传 action; set_auto_follow 传 enabled; set_send_mode 传 mode; speak_text 传 text; read_file 传 path; exec_cmd 传 cmd; set_recognition 传 enabled; set_auto_report 传 enabled; set_vision_mode 传 mode=traffic|barrier; set_adaptive_strategy 传 mode=normal|weak; tablet_set_alarm 传 hour/minute/label; tablet_open_app 传 bundleName; tablet_start_ability 传 bundleName/abilityName/parameters; tablet_open_url 传 url。' +
          '请按物流场景理解用户意图（如去装货点、去卸货点、返仓、暂停、急停），但输出字段必须严格符合上述枚举与格式。' +
          '注意：对于 get_camera_frame 方法，系统会自动获取摄像头画面。你只需要返回标准的JSON任务数组即可。' +
          '不要输出任何解释文本。'
      },
      { role: 'system', content: deps.buildRuntimePrompt() },
      { role: 'user', content: input }
    ]

    const rs = await Page4GatewayLayer.completeOpenClaw(
      deps.gatewayState(),
      messages,
      hosts,
      tokenCandidates,
      deps.connectTimeoutMs(),
      deps.readTimeoutMs(),
      deps.model
    )
    deps.applyGatewayState(rs.state)
    if (rs.ok) {
      const planned: Array<Page4PlannedTask> = deps.mapOpenClawPlan(rs.text)
      if (planned.length > 0) return planned
    }
    return []
  }
}

